// The Unicode emoji of the emoji picker and of the completion after ":" (ADR-0091 §1, ADR-0092 §2). The *.gen.json
// files beside this one are generated by `scripts/task.sh emoji:generate` from the same emoji-test.txt as the server's
// table of the emoji that reactions accept (ADR-0051 §6), so every emoji offered here is one the server accepts, and
// from the CLDR annotations. The base data and the names of each locale are separate chunks, loaded with import()
// when first needed. LICENSE-Unicode.txt is their license; the build copies it into dist/licenses/.

/** The groups of emoji-test.txt in its order, without Component. */
type UnicodeEmojiGroupId =
  | "smileys-emotion"
  | "people-body"
  | "animals-nature"
  | "food-drink"
  | "travel-places"
  | "activities"
  | "objects"
  | "symbols"
  | "flags";

/** A fully-qualified emoji and the Unicode emoji version that added it ("13.1"). */
type UnicodeEmojiVariant = readonly [emoji: string, version: string];

/** An emoji without a skin tone, with its skin tone variants in emoji-test.txt's order when it has any. */
type UnicodeEmoji = readonly [emoji: string, version: string, skins?: readonly UnicodeEmojiVariant[]];

/** The emoji that do not depend on the locale: the groups, each with its emoji in emoji-test.txt's order. */
export type UnicodeEmojiData = {
  /** The Unicode version of emoji-test.txt, the same as the server's `EmojiVersion`. */
  emojiVersion: string;
  /** The CLDR version of the names. */
  cldrVersion: string;
  groups: readonly { id: UnicodeEmojiGroupId; emoji: readonly UnicodeEmoji[] }[];
};

/**
 * The CLDR names of the emoji in a locale. An emoji without a CLDR name in the locale has its `en` name, or else the
 * English name of emoji-test.txt.
 */
export type UnicodeEmojiNames = {
  /** The names of the five skin tone modifiers (U+1F3FB..U+1F3FF). */
  tones: Readonly<Record<string, string>>;
  /** The short name and the keywords (without the name) of each emoji without a skin tone. */
  emoji: Readonly<Record<string, readonly [name: string, keywords: readonly string[]]>>;
  /** The name of each skin tone variant ("waving hand: light skin tone"). */
  skins: Readonly<Record<string, string>>;
};

/** The locales with names, each in a chunk of its own. */
const nameLoaders = {
  en: () => import("./en.gen.json"),
  ja: () => import("./ja.gen.json"),
};

export type UnicodeEmojiLocale = keyof typeof nameLoaders;

function hasNames(tag: string): tag is UnicodeEmojiLocale {
  return Object.hasOwn(nameLoaders, tag);
}

/**
 * The locale of the names to show in `locale`: the locale itself or its language when the data has it, or else `en`
 * (the pseudo-locales `en-XA` and `ar-XB` among them).
 */
export function unicodeEmojiLocale(locale: string): UnicodeEmojiLocale {
  const language = locale.split("-")[0] ?? locale;
  if (hasNames(locale)) return locale;
  if (hasNames(language)) return language;
  return "en";
}

/** Loads the emoji that do not depend on the locale. */
export async function loadUnicodeEmoji(): Promise<UnicodeEmojiData> {
  const data = await import("./base.gen.json");
  // The generator writes the shape of UnicodeEmojiData; TypeScript infers plain arrays and strings from JSON.
  return data.default as unknown as UnicodeEmojiData;
}

/** Loads the names of the emoji in the locale closest to `locale` (`unicodeEmojiLocale`). */
export async function loadUnicodeEmojiNames(locale: string): Promise<UnicodeEmojiNames> {
  const data = await nameLoaders[unicodeEmojiLocale(locale)]();
  // As above: the generator writes the shape of UnicodeEmojiNames.
  return data.default as unknown as UnicodeEmojiNames;
}
